package com.beatoflove.standardcalculator;
import java.time.*;
public final class ReferenceRateTest { static int n;static final LocalDate TODAY=LocalDate.of(2026,11,21);static void eq(String a,String b){n++;if(!a.equals(b))throw new AssertionError(a+" != "+b);}static void bad(String b,String q,String d,String v){n++;try{ReferenceRate.parse(b,q,"USD",d,v,TODAY);throw new AssertionError("accepted invalid row");}catch(IllegalArgumentException|java.time.DateTimeException e){}}public static void main(String[]args){eq(ReferenceRate.parse("THB","USD","USD","2026-11-20","0.025",TODAY).thb(),"40");eq(ReferenceRate.parse("THB","JPY","JPY","2026-11-20","5",TODAY).thb(),"0.2");eq(ReferenceRate.parse("THB","IDR","IDR","2026-11-20","500",TODAY).thb(),"0.002");bad("USD","THB","2026-11-20","40");bad("THB","EUR","2026-11-20","1");bad("THB","USD","2026-11-22","1");bad("THB","USD","invalid","1");bad("THB","USD","2026-11-20","0");bad("THB","USD","2026-11-20","-1");bad("THB","USD","2026-11-20","NaN");bad("THB","USD","2026-11-20","1e9999");System.out.println("ReferenceRateTest: "+n+" passed");}}
